// Placeholders. Replace them, and keep the real values out of version control.
const CFG = {
  // The address a worker reaches this n8n at, up to and including /webhook.
  publicBase: 'https://n8n.example.com/webhook',
  // Goes in every callback_url. The runner adds no header to a callback.
  callbackSecret: 'REPLACE_WITH_CALLBACK_SECRET',
  // Sent by you, not by workers, to the n3-admin webhook.
  adminToken: 'REPLACE_WITH_ADMIN_TOKEN',
  // Offer the same job_key to the same worker again after this long with no callback.
  reofferAfterSecs: 120,
  // Unknown tokens kept as pending machines. More than this are refused and not recorded.
  maxPending: 200,
};
// Demo storage: this workflow's static data. It is saved only when the
// workflow is active, and two executions that both write at the same moment
// overwrite each other (two callbacks in the same second: one is lost).
// Fine for one machine and a smoke test. For real use keep `workers` and
// `jobs` in a database table.
const store = $getWorkflowStaticData('global');
store.workers = store.workers || {};
store.jobs = store.jobs || [];
store.results = store.results || {};
const now = Math.floor(Date.now() / 1000);
const req = $input.first().json;

// Worker identification: the bearer token, by its SHA-256 (the Crypto node).
// The body is what the machine says about itself, a claim, not an identity.
const hasToken = /^Bearer\s+\S{16,}$/i.test(req.headers.authorization || '');
if (!hasToken) return [{ json: { decision: 'forbidden' } }];
const hash = req.token_hash;
const body = req.body || {};
const text = (v) => String(v ?? '').slice(0, 64);

let worker = store.workers[hash];
if (!worker) {
  const pending = Object.values(store.workers).filter((w) => w.status === 'pending').length;
  if (pending >= CFG.maxPending) return [{ json: { decision: 'forbidden' } }];
  worker = store.workers[hash] = { status: 'pending', first_seen: now, last_seen: 0 };
}
// What the machine says about itself, refreshed at most once every five
// minutes: an idle poll that writes nothing cannot overwrite a callback that
// is being recorded at the same moment.
if (now - worker.last_seen >= 300) {
  Object.assign(worker, {
    worker: text(body.worker),
    os: text(body.os),
    arch: text(body.arch),
    version: text(body.version),
    max_slots: Number(body.max_slots) || 0,
    // The address is read from the connection (your reverse proxy), never from the body.
    ip: text(req.headers['x-real-ip'] || (req.headers['x-forwarded-for'] || '').split(',')[0]),
    last_seen: now,
  });
}

// Authorization decision. A machine that is not approved gets 403 and nothing
// else: no task, no image name, no secret.
if (worker.status !== 'approved') return [{ json: { decision: 'forbidden' } }];

// One job per poll. A job offered to a machine stays with that machine:
// job_key only deduplicates there. It is offered again, to the same machine,
// when no callback came within reofferAfterSecs.
const job = store.jobs.find((j) =>
  j.state !== 'done' &&
  (!j.worker_hash || j.worker_hash === hash) &&
  (!j.os || j.os === worker.os) &&
  (!j.offered_to || (j.offered_to === hash && now - j.offered_at >= CFG.reofferAfterSecs))
);
if (!job) return [{ json: { decision: 'none' } }];

job.state = 'offered';
job.offered_to = hash;
job.offered_at = now;
job.offers = (job.offers || 0) + 1;

if (job.via_manifest) {
  // Same origin as the poll URL, so the worker sends its token with the GET.
  const manifest_url = `${CFG.publicBase}/n3-manifest?job_key=${encodeURIComponent(job.job_key)}`;
  return [{ json: { decision: 'manifest', response: { manifest_url } } }];
}
const task = {
  ...job.task,
  job_key: job.job_key,
  callback_url: `${CFG.publicBase}/n3-callback?secret=${encodeURIComponent(CFG.callbackSecret)}`,
};
return [{ json: { decision: 'task', response: { task } } }];

