const store = $getWorkflowStaticData('global');
store.workers = store.workers || {};
store.jobs = store.jobs || [];
store.results = store.results || {};
const now = Math.floor(Date.now() / 1000);
const req = $input.first().json;

// Only the machine the job was offered to may read its manifest.
const hash = req.token_hash;
const key = String((req.query || {}).job_key || '');
const worker = store.workers[hash];
const job = store.jobs.find((j) => j.job_key === key && j.state !== 'done');
if (!worker || worker.status !== 'approved' || !job || job.offered_to !== hash) {
  return [{ json: { decision: 'not_found' } }];
}
// A manifest is one JobRequest. It cannot name another manifest.
const task = {
  ...job.task,
  job_key: job.job_key,
  callback_url: `${CFG.publicBase}/n3-callback?secret=${encodeURIComponent(CFG.callbackSecret)}`,
};
return [{ json: { decision: 'found', response: task } }];

