// `jobs` in a database table.
const store = $getWorkflowStaticData('global');
store.workers = store.workers || {};
store.jobs = store.jobs || [];
store.results = store.results || {};
const now = Math.floor(Date.now() / 1000);
const req = $input.first().json;

if (String((req.query || {}).secret || '') !== CFG.callbackSecret) {
  return [{ json: { decision: 'forbidden' } }];
}
const result = req.body || {};
const id = String(result.id || '');
// Idempotent on the job id: the runner tries three times, and a slow answer
// here can make the same callback arrive twice.
if (id && !store.results[id]) {
  store.results[id] = { ...result, received_at: now };
  const job = store.jobs.find((j) => j.job_key === result.job_key);
  if (job) {
    job.state = 'done';
    job.result = { id, reason: result.reason, exit_code: result.exit_code, duration_secs: result.duration_secs };
    // This says the container ended. Whether the work is done is for the
    // job's own report, or a check of the external system, to say.
    job.container_ok = result.reason === 'exited' && result.exit_code === 0;
  }
}
// Answer at once. The runner waits five seconds per try.
return [{ json: { decision: 'ok' } }];

