// overwrite each other (two callbacks in the same second: one is lost).
// Fine for one machine and a smoke test. For real use keep `workers` and
// `jobs` in a database table.
const store = $getWorkflowStaticData('global');
store.workers = store.workers || {};
store.jobs = store.jobs || [];
store.results = store.results || {};
const now = Math.floor(Date.now() / 1000);
const req = $input.first().json;

if ((req.headers.authorization || '') !== `Bearer ${CFG.adminToken}`) {
  return [{ json: { decision: 'forbidden' } }];
}
const body = req.body || {};
const view = () => ({
  workers: Object.entries(store.workers).map(([token_hash, w]) => ({ token_hash, ...w })),
  jobs: store.jobs,
});
const fail = (error) => [{ json: { decision: 'ok', response: { error } } }];

if (body.action === 'approve' || body.action === 'revoke') {
  const worker = store.workers[String(body.token_hash || '')];
  if (!worker) return fail('unknown token_hash');
  worker.status = body.action === 'approve' ? 'approved' : 'revoked';
} else if (body.action === 'enqueue') {
  const job = body.job || {};
  if (!/^[A-Za-z0-9._:-]{1,200}$/.test(String(job.job_key || ''))) return fail('job.job_key is missing or invalid');
  if (!job.task || typeof job.task.image !== 'string') return fail('job.task.image is missing');
  if (store.jobs.some((j) => j.job_key === job.job_key)) return fail('job_key already queued; a new attempt needs a new key');
  store.jobs.push({
    job_key: job.job_key,
    task: job.task,
    via_manifest: !!job.via_manifest,
    os: job.os || null,
    worker_hash: job.worker_hash || null,
    state: 'queued',
    queued_at: now,
  });
} else if (body.action === 'reset') {
  store.workers = {};
  store.jobs = [];
  store.results = {};
} else if (body.action !== 'list') {
  return fail('action is one of list, approve, revoke, enqueue, reset');
}
return [{ json: { decision: 'ok', response: view() } }];
